.xbdeal-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1a2236;
    background: linear-gradient(165deg, #f4f5f8 0%, #eef0f5 55%, #e9ecf3 100%);
    border-radius: 18px;
}

.xbdeal-container * {
    box-sizing: border-box;
}

.xbdeal-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0a1530 0%, #12224d 55%, #1c3566 100%);
    color: #f3f6fc;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(10, 21, 48, 0.34);
    border: 1px solid rgba(199, 162, 90, 0.20);
}

.xbdeal-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.xbdeal-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e3c585;
    background: rgba(199, 162, 90, 0.12);
    border: 1px solid rgba(199, 162, 90, 0.42);
    padding: 5px 14px;
    border-radius: 999px;
}

.xbdeal-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c7d2e6;
}

.xbdeal-parties {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.xbdeal-party {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(26, 34, 54, 0.08);
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.xbdeal-party-acquirer { border-left: 5px solid #12224d; }
.xbdeal-party-target { border-left: 5px solid #c7a25a; }

.xbdeal-party-role {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 800;
    color: #8694ac;
}

.xbdeal-party-name {
    font-weight: 800;
    font-size: 1.08rem;
    color: #12224d;
}

.xbdeal-party-target .xbdeal-party-name { color: #9c7320; }

.xbdeal-party-meta {
    font-size: 0.8rem;
    color: #5d6a82;
    line-height: 1.4;
}

.xbdeal-party-arrow {
    align-self: center;
    font-size: 1.8rem;
    font-weight: 800;
    color: #1c3566;
}

.xbdeal-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44516b;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.xbdeal-period-counter #currentDay,
.xbdeal-period-counter #maxPeriods {
    font-weight: 800;
    color: #12224d;
}

.xbdeal-round-name {
    background: rgba(28, 53, 102, 0.12);
    color: #1c3566;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.xbdeal-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9c7320;
    background: rgba(199, 162, 90, 0.16);
    border: 1px solid rgba(199, 162, 90, 0.36);
    padding: 4px 12px;
    border-radius: 999px;
}

.xbdeal-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.xbdeal-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(26, 34, 54, 0.08);
    border-top: 4px solid #12224d;
}

.xbdeal-card-npv { border-top-color: #1f8a5b; }
.xbdeal-card-completion { border-top-color: #1c3566; }
.xbdeal-card-leverage { border-top-color: #c7a25a; }
.xbdeal-card-risk { border-top-color: #b04444; }

.xbdeal-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7890;
}

.xbdeal-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #12224d;
    font-variant-numeric: tabular-nums;
}

.xbdeal-card-npv .xbdeal-value { color: #1f8a5b; }
.xbdeal-card-completion .xbdeal-value { color: #1c3566; }
.xbdeal-card-leverage .xbdeal-value { color: #9c7320; }
.xbdeal-card-risk .xbdeal-value { color: #b04444; }

.xbdeal-sublabel {
    font-size: 0.75rem;
    color: #76839a;
    line-height: 1.35;
}

/* State colour shifts the math drives. */
.xbdeal-card-npv.xbdeal-npv-loss { border-top-color: #b04444; }
.xbdeal-card-npv.xbdeal-npv-loss .xbdeal-value { color: #b04444; }

.xbdeal-card-leverage.xbdeal-lev-breach { border-top-color: #b04444; }
.xbdeal-card-leverage.xbdeal-lev-breach .xbdeal-value { color: #b04444; }
.xbdeal-card-leverage.xbdeal-lev-ok { border-top-color: #1f8a5b; }
.xbdeal-card-leverage.xbdeal-lev-ok .xbdeal-value { color: #1f8a5b; }

.xbdeal-card-completion.xbdeal-comp-good .xbdeal-value { color: #1f8a5b; }
.xbdeal-card-completion.xbdeal-comp-low .xbdeal-value { color: #b04444; }

.xbdeal-bid-bar {
    display: flex;
    justify-content: flex-start;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    background: #ffffff;
    border: 1px solid #dbe1ea;
    color: #44516b;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.xbdeal-bid-bar #bidDisplay {
    font-size: 1.1rem;
    color: #12224d;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.xbdeal-bid-bar .xbdeal-bid-walk {
    margin-left: 14px;
    color: #6b7890;
}

.xbdeal-bid-bar #walkDisplay {
    font-size: 1.05rem;
    color: #9c7320;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.xbdeal-bid-bar.xbdeal-bid-over #bidDisplay { color: #b04444; }

.xbdeal-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1c3566;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 34, 54, 0.07);
}

.xbdeal-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.xbdeal-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #12224d;
    margin-bottom: 6px;
}

.xbdeal-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4761;
}

.xbdeal-briefing-text strong { color: #1c3566; }
.xbdeal-briefing-text em { color: #9c7320; font-style: italic; }

.xbdeal-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 34, 54, 0.07);
}

.xbdeal-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #12224d;
    border-bottom: 2px solid #e6e9f0;
    padding-bottom: 8px;
}

.xbdeal-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28344c;
    margin: 14px 0 6px;
}

.xbdeal-container select,
.xbdeal-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3cbd8;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1a2236;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.xbdeal-container select:focus,
.xbdeal-container input[type="number"]:focus {
    outline: none;
    border-color: #1c3566;
    box-shadow: 0 0 0 3px rgba(28, 53, 102, 0.15);
}

.xbdeal-container select option {
    background-color: #ffffff;
    color: #1a2236;
}

.xbdeal-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1c3566;
}

.xbdeal-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #44516b;
    margin-top: 4px;
}

.xbdeal-range-readout #cashReadout,
.xbdeal-range-readout #equityReadout {
    color: #1c3566;
    font-weight: 800;
}

.xbdeal-hint {
    font-size: 0.8rem;
    color: #76839a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.xbdeal-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.xbdeal-container .btn-primary {
    background: linear-gradient(135deg, #12224d 0%, #1c3566 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(18, 34, 77, 0.32);
}

.xbdeal-container .btn-primary:hover {
    filter: brightness(1.12);
}

.xbdeal-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c3cbd8;
    color: #5d6a82;
    background: transparent;
}

.xbdeal-coach {
    background: linear-gradient(160deg, #0a1530 0%, #12224d 100%);
    color: #dde5f3;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(10, 21, 48, 0.26);
    border: 1px solid rgba(199, 162, 90, 0.18);
}

.xbdeal-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e3c585;
    margin-bottom: 8px;
}

.xbdeal-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.xbdeal-coach-body strong { color: #8fc9a8; }
.xbdeal-coach-body em { color: #e3c585; font-style: italic; }

.xbdeal-history,
.xbdeal-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(26, 34, 54, 0.07);
}

.xbdeal-history h3,
.xbdeal-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #12224d;
}

.xbdeal-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4761;
}

.xbdeal-container table#usfHistoryTable th {
    background: #eef1f6;
    color: #1c3566;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6dde7;
}

.xbdeal-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f4;
    color: #3a4761;
}

.xbdeal-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.xbdeal-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .xbdeal-container {
        padding: 14px;
    }
    .xbdeal-header h1 {
        font-size: 1.7rem;
    }
    .xbdeal-parties {
        flex-direction: column;
    }
    .xbdeal-party-arrow {
        transform: rotate(90deg);
    }
    .xbdeal-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .xbdeal-value {
        font-size: 2rem;
    }
    .xbdeal-clock {
        margin-left: 0;
    }
    .xbdeal-period-counter {
        font-size: 0.88rem;
    }
    .xbdeal-bid-bar {
        flex-direction: column;
        align-items: flex-start;
        gap: 4px;
    }
    .xbdeal-bid-bar .xbdeal-bid-walk {
        margin-left: 0;
    }
    .xbdeal-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, xbdeal-cm-*) ===== */
.xbdeal-cm { color: #1f2d3a; font-family: inherit; }
.xbdeal-cm-generic { font-size: 15px; text-align: center; }
.xbdeal-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(31,45,58,0.12); margin-bottom: 16px; }
.xbdeal-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #2f6f8f; }
.xbdeal-cm-score-max { font-size: 20px; font-weight: 500; color: #78838f; margin-left: 2px; }
.xbdeal-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #1f2d3a; }
.xbdeal-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #78838f; margin-top: 4px; }
.xbdeal-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.xbdeal-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(47,111,143,0.07); border: 1px solid rgba(47,111,143,0.18); border-radius: 10px; padding: 10px 8px; text-align: center; }
.xbdeal-cm-kpi-val { display: block; font-size: 21px; font-weight: 700; color: #1f2d3a; }
.xbdeal-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #55636e; }
.xbdeal-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.xbdeal-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.xbdeal-cm-chip.is-met { background: rgba(46,143,107,0.14); border-color: rgba(46,143,107,0.42); color: #1f6e50; }
.xbdeal-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.xbdeal-cm-insights { margin: 0; padding-left: 18px; }
.xbdeal-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #34424e; margin-bottom: 7px; }

