(function() {
    'use strict';

    class CrossBorderDealAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Cross-Border Deal`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Hexagone / PolnaChem). ----
            this.TARGET_EBITDA = 60;      // €60M target EBITDA
            this.COMP_LOW = 6.5;          // comparable-deal multiple floor
            this.COMP_HIGH = 7.0;         // comparable-deal multiple ceiling
            this.OWNERS_ASK = 8.5;        // owners want 8.5x (≈ €510M)
            this.ESG_REMEDIATION = 45;    // €45M remediation capex
            this.LEV_CEILING = 2.5;       // ≤ 2.5x post-close leverage ceiling
            this.SLF_BENEFIT = 35;        // ≈ 35 bps sustainability-linked margin benefit
            this.MAX_SYNERGY = 130;       // gross synergy pool the platform can create (€M, PV)
            this.PER_TURN = 6;            // €6M of price per 0.1x on €60M EBITDA

            // Concept truths used by the math.
            this.FAIR_BID = 7.5;          // a synergy-backed bid that clears comps, under walk-away
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    npv: 0,                  // value created (€M)
                    completion: 50,          // completion probability (%)
                    leverage: 1.8,           // post-close leverage (x EBITDA)
                    risk: 72,                // ESG & trust risk index 0–100 (lower safer)
                    bid: this.OWNERS_ASK,    // committed bid multiple (set in R2)
                    walk: this.OWNERS_ASK,   // committed walk-away multiple (set in R2)

                    // ---- Sticky run-defining penalty flags (set when the error is committed). ----
                    esgIgnored: false,       // didn't price the €45M remediation / transition risk
                    trustIgnored: false,     // ignored founder dependency / no synergy haircut / no lock-in
                    diligenceSkipped: false, // skipped the mandated diligence to move fast
                    winnersCurse: false,     // bid above walk-away / chased the rival above discipline
                    leverageBreach: false,   // post-close leverage breached the 2.5x ceiling
                    walkedAway: false,       // walked from the platform entirely

                    slfUsed: false,          // used the sustainability-linked facility
                    lockedIn: false,         // founder locked in
                    earnoutOnBoth: false,    // earn-out on ESG + retention

                    npvHistory: [0],
                    completionHistory: [50],
                    leverageHistory: [1.8],
                    riskHistory: [72],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    diligence: `speed`,
                    esgFinding: `dismiss`,
                    trustFinding: `ignore`,
                    esgAdj: `none`,
                    synergy: `none`,
                    walk: this.OWNERS_ASK,
                    bid: this.OWNERS_ASK,
                    cash: 100,
                    earnout: `none`,
                    lockin: `none`,
                    slf: `standard`,
                    rival: `raise`,
                    case: `strategic`,
                    postmortem: `deny`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const di = document.getElementById(`diligenceInput`);
                const es = document.getElementById(`esgFindingInput`);
                const tr = document.getElementById(`trustFindingInput`);
                if (di) decisions.diligence = di.value;
                if (es) decisions.esgFinding = es.value;
                if (tr) decisions.trustFinding = tr.value;
            } else if (round === 2) {
                const ea = document.getElementById(`esgAdjInput`);
                const sy = document.getElementById(`synergyInput`);
                const wa = document.getElementById(`walkInput`);
                const bi = document.getElementById(`bidInput`);
                if (ea) decisions.esgAdj = ea.value;
                if (sy) decisions.synergy = sy.value;
                if (wa) decisions.walk = parseFloat(wa.value);
                if (bi) decisions.bid = parseFloat(bi.value);
                if (!Number.isFinite(decisions.walk) || decisions.walk < 5 || decisions.walk > 9) {
                    warn(`warn_walk_range`); return false;
                }
                if (!Number.isFinite(decisions.bid) || decisions.bid < 5 || decisions.bid > 9) {
                    warn(`warn_bid_range`); return false;
                }
            } else if (round === 3) {
                const ca = document.getElementById(`cashInput`);
                const er = document.getElementById(`earnoutInput`);
                const lo = document.getElementById(`lockinInput`);
                const sl = document.getElementById(`slfInput`);
                if (ca) decisions.cash = parseInt(ca.value, 10);
                if (er) decisions.earnout = er.value;
                if (lo) decisions.lockin = lo.value;
                if (sl) decisions.slf = sl.value;
                if (!Number.isFinite(decisions.cash) || decisions.cash < 0 || decisions.cash > 100) {
                    warn(`warn_cash_range`); return false;
                }
            } else if (round === 4) {
                const ri = document.getElementById(`rivalInput`);
                const cs = document.getElementById(`caseInput`);
                const pm = document.getElementById(`postmortemInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ri) decisions.rival = ri.value;
                if (cs) decisions.case = cs.value;
                if (pm) decisions.postmortem = pm.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let npvDelta = 0, completionDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Screen and diligence (Common Error 5: speed over diligence). ----
                switch (d.diligence) {
                    case `both`:
                        riskDelta -= 14; completionDelta += 6; coachKey = `coach_r1_both`;
                        break;
                    case `esgonly`:
                        riskDelta -= 5; ds.trustIgnored = true; coachKey = `coach_r1_esgonly`;
                        break;
                    case `speed`:
                        // Fast and blind — the prior deal's failure mode. Sticky.
                        riskDelta += 12; completionDelta += 4; ds.diligenceSkipped = true;
                        ds.esgIgnored = true; ds.trustIgnored = true; coachKey = `coach_r1_speed`;
                        break;
                }

                // ESG dossier read.
                switch (d.esgFinding) {
                    case `flag`:
                        riskDelta -= 8; coachKey = (d.diligence === `both`) ? `coach_r1_sharp` : coachKey;
                        break;
                    case `dismiss`:
                        riskDelta += 6; ds.esgIgnored = true; coachKey = `coach_r1_esgdismiss`;
                        break;
                    case `dealbreaker`:
                        // Over-reads it — abandons a value-creating platform over a priceable gap.
                        riskDelta -= 2; ds.walkedAway = true; coachKey = `coach_r1_esgwalk`;
                        break;
                }

                // Trust diligence read.
                switch (d.trustFinding) {
                    case `quantify`:
                        riskDelta -= 8; completionDelta += 2;
                        break;
                    case `ignore`:
                        riskDelta += 6; ds.trustIgnored = true; coachKey = (coachKey === `coach_default`) ? `coach_r1_trustignore` : coachKey;
                        break;
                    case `overstate`:
                        riskDelta -= 1; ds.walkedAway = true; coachKey = `coach_r1_trustwalk`;
                        break;
                }

                summaryKey = (d.diligence === `both` && d.esgFinding === `flag` && d.trustFinding === `quantify`) ? `sum_r1_good` :
                             (d.diligence === `speed` ? `sum_r1_speed` : `sum_r1_weak`);
            } else if (round === 2) {
                // ---- Price the bid (Common Errors 1 & 2: financials-only & winner's curse). ----
                ds.walk = d.walk;
                ds.bid = d.bid;

                // (a) ESG adjustment — is the €45M remediation + transition risk in the price?
                switch (d.esgAdj) {
                    case `full`:
                        npvDelta += 18; riskDelta -= 12; ds.esgIgnored = false; coachKey = `coach_r2_esgfull`;
                        break;
                    case `partial`:
                        npvDelta += 6; riskDelta -= 4; coachKey = `coach_r2_esgpartial`;
                        break;
                    case `none`:
                        // Financials-only pricing — the €45M hits post-close. Sticky.
                        npvDelta -= 20; riskDelta += 10; ds.esgIgnored = true; coachKey = `coach_r2_esgnone`;
                        break;
                }

                // (b) Trust/founder synergy haircut.
                switch (d.synergy) {
                    case `full`:
                        npvDelta += 14; riskDelta -= 10; ds.trustIgnored = false; coachKey = (coachKey === `coach_default`) ? `coach_r2_synfull` : coachKey;
                        break;
                    case `light`:
                        npvDelta += 3; riskDelta -= 2;
                        break;
                    case `none`:
                        npvDelta -= 12; riskDelta += 8; ds.trustIgnored = true; coachKey = (coachKey === `coach_default`) ? `coach_r2_synnone` : coachKey;
                        break;
                }

                // (c) Walk-away discipline & the bid itself.
                // Premium over comps must be backed by realisable synergy; bid > walk-away is the winner's curse.
                const premiumTurns = Math.max(0, d.bid - this.COMP_HIGH);     // turns above comps
                // Synergy-backed value of the premium: a fair bid up to ~7.5x is supported; above that, value erodes fast.
                if (d.bid <= this.FAIR_BID + 0.05) {
                    npvDelta += 14 - premiumTurns * this.PER_TURN * 0.8;       // disciplined, synergy-backed
                } else {
                    // Over-paying: each extra turn destroys value (price runs ahead of synergy).
                    npvDelta += 14 - (this.FAIR_BID - this.COMP_HIGH) * this.PER_TURN * 0.8
                                   - (d.bid - this.FAIR_BID) * this.PER_TURN * 2.2;
                }

                if (d.bid > d.walk + 0.001) {
                    // Crossed your own walk-away in the pricing round — undisciplined. Sticky.
                    ds.winnersCurse = true; npvDelta -= 16; coachKey = `coach_r2_crosswalk`;
                }
                if (d.walk > this.COMP_HIGH + 1.0) {
                    // Walk-away set near the owners' ask = no discipline at all.
                    riskDelta += 4;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_walkhigh`;
                }
                if (d.bid >= this.OWNERS_ASK - 0.05) {
                    // Paying at/above the owners' 8.5x ask.
                    ds.winnersCurse = true; coachKey = `coach_r2_overpay`;
                }

                // Completion: a credible, synergy-backed bid above comps improves the chance vs. the rival.
                completionDelta += Math.max(-6, Math.min(14, (d.bid - this.COMP_LOW) * 8));
                if (d.bid < this.COMP_LOW) { completionDelta -= 12; coachKey = `coach_r2_underbid`; }

                if (coachKey === `coach_default`) coachKey = `coach_r2_balanced`;
                summaryKey = (d.esgAdj === `full` && d.synergy === `full` && !ds.winnersCurse && d.bid >= this.COMP_HIGH) ? `sum_r2_good` :
                             (ds.winnersCurse ? `sum_r2_curse` :
                             (ds.esgIgnored ? `sum_r2_esgnone` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Structure under the financing constraint (Common Errors 3 & 4). ----
                const cashShare = d.cash / 100;

                // Post-close leverage: all-cash at the committed bid drives leverage; equity/paper lowers it.
                // Base 1.8x; an all-cash bid at ~8.5x reaches ~2.7x. Equity share pulls it back down.
                const bidPressure = (ds.bid - this.COMP_HIGH);                       // turns of premium funded
                const allCashLeverage = 1.8 + 0.45 + Math.max(0, bidPressure) * 0.18; // ~2.7x at 8.5x all-cash
                ds.leverage = Math.round((1.8 + (allCashLeverage - 1.8) * cashShare) * 100) / 100;
                if (ds.leverage > this.LEV_CEILING + 0.001) {
                    ds.leverageBreach = true;
                    completionDelta -= 14; npvDelta -= 10; coachKey = `coach_r3_breach`;
                } else {
                    ds.leverageBreach = false;
                    completionDelta += 6;
                }
                // Heavy equity/paper dilutes value if used beyond what discipline needs.
                if (cashShare <= 0.55) { npvDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r3_overdilute`; }

                // Earn-out / deferred consideration — bridges the gap, transfers risk.
                switch (d.earnout) {
                    case `both`:
                        npvDelta += 12; riskDelta -= 10; completionDelta += 8; ds.earnoutOnBoth = true;
                        coachKey = (coachKey === `coach_default`) ? `coach_r3_earnboth` : coachKey;
                        break;
                    case `esg`:
                        npvDelta += 5; riskDelta -= 4; completionDelta += 3;
                        break;
                    case `none`:
                        npvDelta -= 5; riskDelta += 4; completionDelta -= 4;
                        break;
                }

                // Founder lock-in & reps — protects the trust/customer synergy and the permit gap.
                switch (d.lockin) {
                    case `full`:
                        npvDelta += 14; riskDelta -= 12; ds.lockedIn = true; ds.trustIgnored = false;
                        coachKey = (coachKey === `coach_default`) ? `coach_r3_lockfull` : coachKey;
                        break;
                    case `reps`:
                        npvDelta += 4; riskDelta -= 4;
                        break;
                    case `none`:
                        // All-cash clean exit loses the relationships the synergy depended on. Sticky.
                        npvDelta -= 12; riskDelta += 10; ds.trustIgnored = true; coachKey = `coach_r3_locknone`;
                        break;
                }

                // Sustainability-linked facility — 35 bps benefit, lowers financing cost, aligns incentives.
                if (d.slf === `slf`) {
                    ds.slfUsed = true; npvDelta += 8; completionDelta += 4; riskDelta -= 6;
                    ds.leverage = Math.round((ds.leverage - 0.08) * 100) / 100; // cheaper facility eases the ratio at the margin
                    if (ds.leverage <= this.LEV_CEILING + 0.001) ds.leverageBreach = false;
                    if (coachKey === `coach_default` || coachKey === `coach_r3_earnboth` || coachKey === `coach_r3_lockfull`) coachKey = `coach_r3_slf`;
                } else {
                    npvDelta -= 2;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_noslf`;
                }

                summaryKey = (!ds.leverageBreach && d.lockin === `full` && d.earnout === `both` && ds.slfUsed) ? `sum_r3_good` :
                             (ds.leverageBreach ? `sum_r3_breach` :
                             (d.lockin === `none` ? `sum_r3_locknone` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Recommend to the IC & react to the rival escalation (Common Error 2). ----
                switch (d.rival) {
                    case `hold`:
                        // Discipline holds — winning and creating value are not the same thing.
                        completionDelta += 4; npvDelta += 8; riskDelta -= 6; coachKey = `coach_r4_hold`;
                        break;
                    case `capitulate`:
                        // Matching at 8.7x is above any disciplined walk-away — winner's curse.
                        ds.winnersCurse = true; ds.bid = 8.7; npvDelta -= 14; completionDelta += 6; riskDelta += 4;
                        coachKey = `coach_r4_capitulate`;
                        break;
                    case `raise`:
                        // Raising to 8.9x to win — the textbook winner's curse; also re-breaches leverage.
                        ds.winnersCurse = true; ds.bid = 8.9; npvDelta -= 22; completionDelta += 8; riskDelta += 8;
                        ds.leverage = Math.round((ds.leverage + 0.25) * 100) / 100;
                        if (ds.leverage > this.LEV_CEILING + 0.001) ds.leverageBreach = true;
                        coachKey = `coach_r4_raise`;
                        break;
                }

                // The IC case framing.
                switch (d.case) {
                    case `integrated`:
                        npvDelta += 8; completionDelta += 6; riskDelta -= 6; coachKey = (d.rival === `hold`) ? `coach_r4_integrated` : coachKey;
                        break;
                    case `strategic`:
                        completionDelta += 2; riskDelta += 2; if (coachKey === `coach_default`) coachKey = `coach_r4_strategic`;
                        break;
                    case `price`:
                        npvDelta -= 4; riskDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r4_priceonly`;
                        break;
                }

                // Post-mortem pre-emption.
                switch (d.postmortem) {
                    case `both`:
                        npvDelta += 6; riskDelta -= 8;
                        break;
                    case `esg`:
                        npvDelta += 2; riskDelta -= 3;
                        break;
                    case `deny`:
                        npvDelta -= 4; riskDelta += 6; if (coachKey === `coach_default`) coachKey = `coach_r4_deny`;
                        break;
                }

                if (d.conviction >= 60) { npvDelta += 3; riskDelta -= 3; }
                else if (d.conviction <= 25) { riskDelta += 4; }

                summaryKey = (d.rival === `hold` && d.case === `integrated` && d.postmortem === `both`) ? `sum_r4_good` :
                             (ds.winnersCurse ? `sum_r4_curse` : `sum_r4_weak`);
            }

            // ---- Apply deltas. ----
            ds.npv = Math.round((ds.npv + npvDelta) * 10) / 10;
            ds.completion = Math.max(0, Math.min(99, Math.round(ds.completion + completionDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            // ---- Sticky penalty GATES — cap KPIs so a headline error can't post a top result. ----
            // Walking the platform entirely zeroes the value created (no deal, no synergy).
            if (ds.walkedAway) {
                ds.npv = Math.min(ds.npv, 0);
                ds.completion = Math.min(ds.completion, 5);
            }
            // Financials-only pricing: the unpriced €45M caps value.
            if (ds.esgIgnored) ds.npv = Math.min(ds.npv, 14);
            // Ignored trust/founder dependency: synergy haircut caps value.
            if (ds.trustIgnored) ds.npv = Math.min(ds.npv, 22);
            // Winner's curse: a premium unbacked by synergy can't create value.
            if (ds.winnersCurse) ds.npv = Math.min(ds.npv, 8);
            // Leverage breach: the deal can't clear the IC on discipline grounds.
            if (ds.leverageBreach) { ds.npv = Math.min(ds.npv, 6); ds.completion = Math.min(ds.completion, 45); }
            // Skipping the mandated diligence repeats the last failure — hard cap.
            if (ds.diligenceSkipped) ds.npv = Math.min(ds.npv, 10);

            ds.npv = Math.round(ds.npv * 10) / 10;

            ds.npvHistory.push(ds.npv);
            ds.completionHistory.push(ds.completion);
            ds.leverageHistory.push(ds.leverage);
            ds.riskHistory.push(ds.risk);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                npv: ds.npv,
                npvDelta: Math.round(npvDelta * 10) / 10,
                completion: ds.completion,
                leverage: ds.leverage,
                risk: ds.risk,
                bid: ds.bid,
                walk: ds.walk,
                esgIgnored: ds.esgIgnored,
                trustIgnored: ds.trustIgnored,
                winnersCurse: ds.winnersCurse,
                leverageBreach: ds.leverageBreach,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _riskLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 55) return t(`risk_high`);
            if (v >= 32) return t(`risk_mid`);
            return t(`risk_low`);
        }

        _fmtMult(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `x`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`npvDisplay`, `domainState.npv`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.xbdeal-card-npv`);
                if (card) card.classList.toggle(`xbdeal-npv-loss`, n < 0);
                return `€${n}M`;
            });

            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.xbdeal-card-completion`);
                if (card) {
                    card.classList.toggle(`xbdeal-comp-good`, n >= 70);
                    card.classList.toggle(`xbdeal-comp-low`, n < 45);
                }
                return `${n}%`;
            });

            uiManager.bind(`leverageDisplay`, `domainState.leverage`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.xbdeal-card-leverage`);
                if (card) {
                    card.classList.toggle(`xbdeal-lev-breach`, n > self.LEV_CEILING + 0.001);
                    card.classList.toggle(`xbdeal-lev-ok`, n <= self.LEV_CEILING + 0.001);
                }
                return self._fmtMult(n);
            });

            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => self._riskLabel(Number(v)));

            uiManager.bind(`bidDisplay`, `domainState.bid`, (v) => {
                const bid = Number(v);
                const ds = window.mySimulation.state.domainState;
                const bar = document.querySelector(`.xbdeal-bid-bar`);
                if (bar) bar.classList.toggle(`xbdeal-bid-over`, ds && bid > Number(ds.walk) + 0.001);
                return self._fmtMult(bid);
            });
            uiManager.bind(`walkDisplay`, `domainState.walk`, (v) => self._fmtMult(Number(v)));

            // Cash/equity slider readout.
            const ca = document.getElementById(`cashInput`);
            const caReadout = document.getElementById(`cashReadout`);
            const eqReadout = document.getElementById(`equityReadout`);
            if (ca && caReadout) {
                const sync = function() {
                    caReadout.textContent = ca.value;
                    if (eqReadout) eqReadout.textContent = String(100 - parseInt(ca.value, 10));
                };
                sync();
                ca.addEventListener(`input`, sync);
            }
        }

        getChartConfig() {
            return {
                xbdealChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_npv`) : `Deal NPV (€M)`,
                                data: [],
                                borderColor: `#1f8a5b`,
                                backgroundColor: `rgba(31,138,91,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f8a5b`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_completion`) : `Completion probability (%)`,
                                data: [],
                                borderColor: `#1c3566`,
                                backgroundColor: `rgba(28,53,102,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#1c3566`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_leverage`) : `Post-close leverage (×10)`,
                                data: [],
                                borderColor: `#c7a25a`,
                                backgroundColor: `rgba(199,162,90,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c7a25a`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#44516b`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, position: `left`,
                                ticks: { color: `#76839a` }, grid: { color: `rgba(26,34,54,0.06)` },
                                title: { display: true, text: `€M · % · leverage×10`, color: `#76839a` }
                            },
                            x: {
                                ticks: { color: `#76839a` }, grid: { color: `rgba(26,34,54,0.04)` },
                                title: { display: true, text: `Round`, color: `#76839a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.npvHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            const leverageScaled = ds.leverageHistory.map((v) => Math.round(v * 10));
            return {
                xbdealChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.npvHistory.map((v) => Math.round(v)) },
                        { data: ds.completionHistory },
                        { data: leverageScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, single source of truth, persisted every period so the
            // grading/analytics/LTI layer (domainState.performance.overallScore then top-level
            // score) receives a number instead of null -> 0.0.
            const npv = Math.round(ds.npv);
            const completion = Math.round(ds.completion);
            const risk = Math.round(ds.risk);
            const riskScore = 100 - risk;
            const npvScore = Math.max(0, Math.min(100, npv));
            return Math.round(npvScore * 0.40 + completion * 0.28 + riskScore * 0.32);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const npv = Math.round(ds.npv);
            const completion = Math.round(ds.completion);
            const leverage = Math.round(ds.leverage * 100) / 100;
            const risk = Math.round(ds.risk);

            // Composite: value, completion, risk-control, discipline.
            const composite = this._composite(ds);

            const priced = !ds.esgIgnored && !ds.trustIgnored;
            const disciplined = !ds.winnersCurse;
            const underCeiling = !ds.leverageBreach;
            const closed = completion >= 65 && !ds.walkedAway;
            const valueCreated = npv >= 45;

            // ---- Verdict gates: the headline anti-patterns cannot reach the top verdict. ----
            let performance = `Value Destroyed`, performanceKey = `grade_destroyed`;
            if (ds.walkedAway) { performance = `Platform Lost`; performanceKey = `grade_platformlost`; }
            else if (valueCreated && priced && disciplined && underCeiling && closed && composite >= 72) { performance = `Deal Approved`; performanceKey = `grade_approved`; }
            else if (ds.diligenceSkipped) { performance = `Fast and Blind`; performanceKey = `grade_blind`; }
            else if (ds.winnersCurse) { performance = `Winner's Curse`; performanceKey = `grade_curse`; }
            else if (ds.leverageBreach) { performance = `Discipline Breached`; performanceKey = `grade_breach`; }
            else if (ds.esgIgnored || ds.trustIgnored) { performance = `Mispriced`; performanceKey = `grade_mispriced`; }
            else if (npv >= 20 && composite >= 55) { performance = `IC Deferred`; performanceKey = `grade_deferred`; }

            const insights = [];
            if (performance === `Deal Approved`) insights.push(window.mySimulation.t(`insight_approved`));
            else if (ds.walkedAway) insights.push(window.mySimulation.t(`insight_walked`));
            else if (ds.diligenceSkipped) insights.push(window.mySimulation.t(`insight_blind`));
            else if (ds.winnersCurse) insights.push(window.mySimulation.t(`insight_curse`));
            else if (ds.leverageBreach) insights.push(window.mySimulation.t(`insight_breach`));
            else if (ds.esgIgnored || ds.trustIgnored) insights.push(window.mySimulation.t(`insight_mispriced`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.esgIgnored) insights.push(window.mySimulation.t(`insight_esg`));
            if (ds.trustIgnored) insights.push(window.mySimulation.t(`insight_trust`));
            if (ds.leverageBreach) insights.push(window.mySimulation.t(`insight_leverage`));
            if (ds.slfUsed && underCeiling) insights.push(window.mySimulation.t(`insight_slf`));
            if (ds.lockedIn && !ds.trustIgnored) insights.push(window.mySimulation.t(`insight_lockin`));

            return {
                npv: npv,
                completion: completion,
                leverage: leverage,
                risk: risk,
                priced: priced,
                disciplined: disciplined,
                underCeiling: underCeiling,
                closed: closed,
                valueCreated: valueCreated,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="xbdeal-cm"><p class="xbdeal-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="xbdeal-cm-kpi"><span class="xbdeal-cm-kpi-val">${valStr}</span>`
                + `<span class="xbdeal-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="xbdeal-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="xbdeal-cm">`
                +   `<div class="xbdeal-cm-scoreband">`
                +     `<div class="xbdeal-cm-score">${summary.composite}<span class="xbdeal-cm-score-max">/100</span></div>`
                +     `<div class="xbdeal-cm-tier">${tier}</div>`
                +     `<div class="xbdeal-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="xbdeal-cm-kpis">`
                +     kpi(`cm_kpi_npv`, `€` + String(Math.round(summary.npv)) + `M`)
                +     kpi(`cm_kpi_completion`, String(Math.round(summary.completion)) + `%`)
                +     kpi(`cm_kpi_leverage`, self._fmtMult(summary.leverage))
                +     kpi(`cm_kpi_risk`, String(Math.round(summary.risk)))
                +   `</div>`
                +   `<div class="xbdeal-cm-chips">`
                +     chip(summary.valueCreated, `cm_chip_value`)
                +     chip(summary.priced, `cm_chip_priced`)
                +     chip(summary.disciplined, `cm_chip_disc`)
                +     chip(summary.underCeiling, `cm_chip_ceiling`)
                +     chip(summary.closed, `cm_chip_closed`)
                +   `</div>`
                +   (insights ? `<ul class="xbdeal-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.walkedAway) return window.mySimulation.t(`hint_walked`);
            if (ds.diligenceSkipped) return window.mySimulation.t(`hint_blind`);
            if (ds.leverageBreach) return window.mySimulation.t(`hint_leverage`);
            if (ds.winnersCurse) return window.mySimulation.t(`hint_curse`);
            if (ds.esgIgnored && state.currentPeriod >= 2) return window.mySimulation.t(`hint_esg`);
            if (ds.trustIgnored && state.currentPeriod >= 3) return window.mySimulation.t(`hint_trust`);
            if (ds.risk >= 55) return window.mySimulation.t(`hint_risk`);
            if (ds.npv >= 45 && !ds.leverageBreach && !ds.winnersCurse) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.npv`, label: `NPV`, i18nKey: `col_npv`, formatter: (v) => `€${Math.round(v)}M` },
                { key: `results.completion`, label: `Close`, i18nKey: `col_completion`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.leverage`, label: `Leverage`, i18nKey: `col_leverage`, formatter: (v) => self._fmtMult(Number(v)) },
                { key: `results.risk`, label: `Risk`, i18nKey: `col_risk`, formatter: (v) => self._riskLabel(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

